import{_ as a,a as t,c as n,j as s}from"./chunks/framework.DVzkjf-b.js";const p=JSON.parse('{"title":"English as a Higher Abstraction in Software Engineering","description":"Natural-language-directed work, executable contracts, tests, Agile/Kanban, and human oversight.","frontmatter":{"title":"English as a Higher Abstraction in Software Engineering","description":"Natural-language-directed work, executable contracts, tests, Agile/Kanban, and human oversight."},"headers":[],"relativePath":"research/systems/english-software-engineering.md","filePath":"research/systems/english-software-engineering.md"}'),r={name:"research/systems/english-software-engineering.md"};function i(o,e,c,h,l,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="english-as-a-higher-abstraction-in-software-engineering" tabindex="-1">English as a Higher Abstraction in Software Engineering <a class="header-anchor" href="#english-as-a-higher-abstraction-in-software-engineering" aria-label="Permalink to &quot;English as a Higher Abstraction in Software Engineering&quot;">​</a></h1><p><em>Research essay · November 2026</em></p><p>Software engineering has repeatedly moved upward in abstraction: machine instructions, assembly, general-purpose languages, libraries, and declarative interfaces. With capable AI agents, natural language now belongs in that history.</p><p>But saying <strong>“English is the new computer science”</strong> is a provocation, not a complete engineering theory. Human language is ambiguous, context-dependent, and not directly executable with programming-language guarantees.</p><p>The more precise claim is that software engineers can increasingly work at the <strong>level of goals, constraints, observable behavior, and evaluation</strong>, while agents translate those specifications into code and workflows.</p><h2 id="what-moves-upward" tabindex="-1">What moves upward <a class="header-anchor" href="#what-moves-upward" aria-label="Permalink to &quot;What moves upward&quot;">​</a></h2><p>In my educational projects I use personas and journeys for human goals; themes, epics, and user stories for scope; acceptance criteria for observable behavior; GitHub Issues for bounded tasks; and pull requests, commits, and tests for evidence.</p><p>The development chain is:</p><p><strong>Human intent → approved specification → bounded agent task → implementation → tests and independent review → accepted outcome.</strong></p><p>An important design choice is keeping the source of truth in concise versioned Markdown and executable contracts, rather than large repeated instructions that gradually disagree.</p><h2 id="testing-is-the-agent-harness" tabindex="-1">Testing is the agent harness <a class="header-anchor" href="#testing-is-the-agent-harness" aria-label="Permalink to &quot;Testing is the agent harness&quot;">​</a></h2><p>The <a href="https://github.com/kaw393939/metavis-demo-projects/blob/main/Docs/TDD_STRATEGY.md" target="_blank" rel="noreferrer">MetaVis TDD strategy</a> is a concrete example. It specifies protocol-first design, golden fixtures, deterministic sensor outputs, real hardware tests, and performance budgets. In <a href="https://github.com/kaw393939/metavis-demo-projects/blob/main/Tests/MetaVisSimulationTests/Perf/RenderAllocationTests.swift" target="_blank" rel="noreferrer">MetaVis&#39;s GPU test</a>, merely producing an image is insufficient; resource behavior also has to satisfy an invariant.</p><p>Tests should be tied to user-story acceptance criteria, and implementing agents should not be free to weaken the tests that determine success. LLM-based QA may help examine qualitative outcomes, but does not replace independent measurement or human acceptance.</p><h2 id="kanban-changes-when-agents-are-abundant" tabindex="-1">Kanban changes when agents are abundant <a class="header-anchor" href="#kanban-changes-when-agents-are-abundant" aria-label="Permalink to &quot;Kanban changes when agents are abundant&quot;">​</a></h2><p>When agents can produce code rapidly, human review becomes the constrained resource. The board should not maximize simultaneous agent work. It should pull verified, decision-ready increments to human review at a manageable rate. Review packets should show one runnable outcome, what changed, known limitations, and the specific judgment requested.</p><p>This is not a proposal to copy every ceremony from traditional Scrum. Short reversible fixes need lightweight control notes; architecture changes and consequential releases need stronger specifications and decision records.</p><h2 id="what-research-is-needed" tabindex="-1">What research is needed <a class="header-anchor" href="#what-research-is-needed" aria-label="Permalink to &quot;What research is needed&quot;">​</a></h2><p>Compare vague-prompt development, conventional issue-driven development, and test-governed agent development on matched tasks. Evaluate defects, acceptance coverage, reviewer minutes, rework, recovery, and student comprehension. A passing test suite is not proof that the underlying requirements are complete.</p><p>The academic framing connects to <a href="https://digitalcommons.njit.edu/fac_pubs/16112/" target="_blank" rel="noreferrer">Deek, Turoff and McHugh&#39;s integrated problem-solving/programming model (1999)</a> and <a href="https://digitalcommons.njit.edu/fac_pubs/19489/" target="_blank" rel="noreferrer">DeFranco-Tommarello and Deek&#39;s empirical collaboration study (2005)</a>. Their research offers a basis for studying process, cognition, and collaboration as well as code artifacts.</p><p><strong>The argument is not that low-level knowledge becomes irrelevant.</strong> Specialized Swift, Metal, graph databases, privacy controls, and deterministic execution still matter. The opportunity is to orchestrate them from a higher-level interface while preserving verification and authority.</p><p><a href="./">Research series</a> · <a href="./metavis-evidence-and-evaluation">MetaVis case study</a></p>',21)])])}const u=a(r,[["render",i]]);export{p as __pageData,u as default};
